#include "target-record.h"
struct reader{const unsigned char*b;size_t n,at;};
struct text{size_t start,end;};
static int ch(struct reader*r,unsigned c){if(r->at>=r->n||r->b[r->at]!=c)return 0;r->at++;return 1;}
static int str(struct reader*r,struct text*t){if(!ch(r,'"'))return 0;t->start=r->at;while(r->at<r->n){unsigned c=r->b[r->at++];if(c=='"'){t->end=r->at-1;return 1;}if(c<32||c==127)return 0;if(c=='\\'){if(r->at==r->n)return 0;c=r->b[r->at++];/* Fixed writer only emits these escapes in the admitted path strings. */if(c!='\\'&&c!='"')return 0;}}return 0;}
static int eq(struct reader*r,struct text t,const unsigned char*s,size_t n){size_t at=t.start,i=0;while(at<t.end){unsigned c=r->b[at++];if(c=='\\'){if(at==t.end)return 0;c=r->b[at++];}if(i==n||s[i++]!=c)return 0;}return i==n;}
static int name(struct reader*r,struct text t,const char*s){size_t n=0;while(s[n])n++;return eq(r,t,(const unsigned char*)s,n);}
static int num(struct reader*r,uint64_t*value){size_t start=r->at;uint64_t n=0;while(r->at<r->n&&r->b[r->at]>='0'&&r->b[r->at]<='9'){unsigned c=r->b[r->at++]-'0';if(n>900719925474099ULL||(n==900719925474099ULL&&c>1))return 0;n=n*10+c;}if(r->at==start||(r->at-start>1&&r->b[start]=='0'))return 0;*value=n;return 1;}
static int nonce(struct reader*r,struct text t){size_t i;if(t.end-t.start!=64)return 0;for(i=t.start;i<t.end;i++)if(!((r->b[i]>='0'&&r->b[i]<='9')||(r->b[i]>='a'&&r->b[i]<='f')))return 0;return 1;}
int cl_target_owner_record(const unsigned char*b,size_t n,const struct cl_target_request*q,uint32_t pid,const char*scope_id,const char*root_id){static const char*keys[]={"schemaVersion","kind","root","installationId","engine","epoch","principal","scope","protocol","nonce","pid","endpoint","scopeIdentity","rootIdentity"};struct reader r={b,n,0};unsigned mask=0;struct text key,value;uint64_t number;unsigned field;const char*kind=q&&q->kind==0?"database":q&&q->kind==1?"owner":q&&q->kind==2?"completion":q&&q->kind==3?"services":q&&q->kind==4?"start":q&&q->kind==5?"images":"invalid";if(!b||!q||!pid||!scope_id||!root_id||!n||n>8192||!ch(&r,'{'))return 0;for(;;){if(!str(&r,&key)||!ch(&r,':'))return 0;for(field=0;field<14;field++)if(name(&r,key,keys[field]))break;if(field==14||(mask&(1U<<field)))return 0;mask|=1U<<field;if(field==0||field==5||field==10){if(!num(&r,&number)||number!=(field==0?1:field==5?q->epoch:pid))return 0;}else{struct cl_target_string expected={0,0};if(!str(&r,&value))return 0;if(field==1){if(!name(&r,value,kind))return 0;}else if(field==8){if(!name(&r,value,"castlink-windows-target-operation-v1"))return 0;}else if(field==9){if(!nonce(&r,value)||!eq(&r,value,q->nonce.p,q->nonce.n))return 0;}else if(field==11){if(!name(&r,value,"npipe:////./pipe/dockerDesktopLinuxEngine"))return 0;}else if(field==12||field==13){if(!name(&r,value,field==12?scope_id:root_id))return 0;}else{expected=field==2?q->root:field==3?q->installation:field==4?q->engine:field==6?q->sid:q->scope;if(!eq(&r,value,expected.p,expected.n))return 0;}}if(ch(&r,'}'))break;if(!ch(&r,','))return 0;}return mask==16383&&ch(&r,'\n')&&r.at==r.n;}
int cl_target_epoch_record(const unsigned char*b,size_t n,uint64_t epoch){struct reader r={b,n,0};struct text key;uint64_t value;if(!b||n>8192||!ch(&r,'{')||!str(&r,&key)||!name(&r,key,"epoch")||!ch(&r,':')||!num(&r,&value)||value!=epoch||!ch(&r,'}')||!ch(&r,'\n'))return 0;return r.at==r.n;}
